  const progress = $derived(row ? powerpointTransitionProgress(row, sceneTime) : 1);
  let root = $state(null), stage = $state(null), message = $state(''), drag = $state(null), imageData = $state(''), imageMime = $state('image/png'), findText = $state(''), replacement = $state(''), filename = $state('');
  let originalState, originalProfile, originalId, originalRow, originalWindow, retired = false, facade;
  const current = () => !retired && root?.isConnected === true && powerPointState === originalState && profile === originalProfile && windowId === originalId && row === originalRow && actualWindow === originalWindow;
  async function command(suffix, payload = {}) {
