    if (event.target.matches('input,textarea,select,[contenteditable]')) return;
    if (modifier && !event.target.matches('input,textarea,select,[contenteditable]')) { const suffix = { x: 'cut', c: 'copy', v: 'paste' }[event.key.toLowerCase()]; if (suffix) { event.preventDefault(); command(suffix); return; } }
    if (event.key === 'F5') { event.preventDefault(); command('presentation.start', { from: event.shiftKey ? 'current' : 'beginning' }); }
    else if (event.key === 'Delete' || event.key === 'Backspace') { event.preventDefault(); if (selected.length) command('object.delete'); }
