    drag = { pointerId: event.pointerId, x: event.clientX, y: event.clientY, dx: 0, dy: 0, resize, itemId: item.id, width: item.width, height: item.height, objectX: item.x, objectY: item.y, selectionIds: ids, ready: false };
    const pending = drag, result = await command('object.select', { objectIds: ids });
