  }
  function dragMove(event) { if (!drag || !stage || drag.pointerId !== event.pointerId || !current()) return; const rect = stage.getBoundingClientRect(); drag.dx = (event.clientX - drag.x) / rect.width * row.document.width; drag.dy = (event.clientY - drag.y) / rect.height * row.document.height; }
  function endDrag(event) {
