{#snippet thumbnail(item)}
  <svg viewBox={`0 0 ${row.document.width} ${row.document.height}`} aria-hidden="true"><rect width={row.document.width} height={row.document.height} fill={item.background}/>{#each item.objects as object (object.id)}
