    {:else}
      {#if object.type === 'shape'}{#if object.shape === 'ellipse'}<ellipse cx={object.x + object.width / 2} cy={object.y + object.height / 2} rx={object.width / 2} ry={object.height / 2} fill={object.fill}/>{:else if object.shape === 'line'}<line x1={object.x} y1={object.y} x2={object.x + object.width} y2={object.y + object.height} stroke={object.fill} stroke-width="3"/>{:else}<rect x={object.x} y={object.y} width={object.width} height={object.height} fill={object.fill}/>{/if}{/if}
      <foreignObject x={object.x} y={object.y} width={object.width} height={object.height}><div class="ppt-thumbnail-text" style={`font-family:${documentFonts.css(object.font ?? 'Calibri', object.bold)};font-size:${object.fontSize}px;color:${object.color};font-weight:${object.bold ? 700 : 400}`}>{object.text}</div></foreignObject>
    {/if}
  {/each}</svg>
{/snippet}
{#snippet slideContents(item, editable)}
  {#each item.objects as object (object.id)}
