      {:else}
        {#if object.type === 'shape'}<svg class="ppt-shape" viewBox={`0 0 ${object.width} ${object.height}`} preserveAspectRatio="none" aria-hidden="true">{#if object.shape === 'ellipse'}<ellipse cx={object.width / 2} cy={object.height / 2} rx={object.width / 2} ry={object.height / 2} fill={object.fill}/>{:else if object.shape === 'line'}<line x1="0" y1="0" x2={object.width} y2={object.height} stroke={object.fill} stroke-width="3"/>{:else}<rect width={object.width} height={object.height} fill={object.fill}/>{/if}</svg>{/if}
