{/snippet}

<section bind:this={root} class="office-shell powerpoint powerpoint-app" class:windows={cap.windows} class:classic={cap.classic} class:golden={cap.golden} data-app="powerpoint" data-profile={typeof profile === 'string' ? profile : profile.id} data-powerpoint-window-id={windowId} aria-label="Microsoft PowerPoint" role="region" tabindex="0" onkeydown={keyboard}>
{#if row}
