  <div class="office-ribbon ppt-ribbon" inert={!available || !active}>
  {#if row.tab === 'Home'}
    <div class="office-ribbon-group"><button data-office-control="clipboard-paste" onclick={() => command('paste')}><b>▣</b>Paste Text</button><button data-office-control="clipboard-cut" disabled={!selected.length || selected.some(item => item.type === 'image' || !item.text)} onclick={() => command('cut')}>Cut</button><button data-office-control="clipboard-copy" disabled={!selected.length || selected.some(item => item.type === 'image' || !item.text)} onclick={() => command('copy')}>Copy</button><small>Shared Plain-Text Clipboard</small></div>
    <div class="office-ribbon-group"><button data-office-control="new-slide" onclick={() => command('slide.insert', { layout: 'content' })}><b>⊞</b>New Slide</button><select data-office-control="layout" aria-label="Insert slide layout" value="" onchange={event => { if (event.currentTarget.value) command('slide.insert', { layout: event.currentTarget.value }); }}><option value="">Layout…</option><option value="blank">Blank</option><option value="title">Title only</option><option value="content">Title and Content</option></select><button data-office-control="duplicate-slide" onclick={() => command('slide.duplicate', { slideId: slide.id })}>Duplicate Slide</button><small>Slides</small></div>
    <div class="office-ribbon-group"><label>Font <select data-office-control="font-family" aria-label="Font family" value={first?.font ?? 'Calibri'} disabled={!first || first.type === 'image'} onchange={event => command('object.style', { font: event.currentTarget.value })}>{#each documentFonts.choices(first?.font ?? 'Calibri') as font}<option value={font} disabled={!documentFonts.has(font)}>{font}{!documentFonts.has(font) ? ' (unavailable)' : ''}</option>{/each}</select></label><label>Size <input data-office-control="font-size" type="number" min="6" max="200" value={first?.fontSize ?? 32} disabled={!first || first.type === 'image'} onchange={event => command('object.style', { fontSize: Number(event.currentTarget.value) })}/></label><button data-office-control="bold" aria-pressed={!!first?.bold} disabled={!first || first.type === 'image'} onclick={() => command('object.style', { bold: !first.bold })}><b>B</b></button><label>Font Color <input data-office-control="text-color" type="color" value={first?.color ?? '#242424'} disabled={!first || first.type === 'image'} onchange={event => command('object.style', { color: event.currentTarget.value })}/></label><small>Font</small></div>
    <div class="office-ribbon-group"><button data-office-control="text-box" onclick={() => command('object.insert', { type: 'text' })}>▤ Text Box</button><button data-office-control="delete-object" disabled={!selected.length} onclick={() => command('object.delete')}>Delete</button><button data-office-control="format" disabled={!selected.length} onclick={() => command('dialog', { dialog: 'format' })}>Format Object…</button><small>Drawing</small></div>
    <div class="office-ribbon-group"><button data-office-control="find-dialog" onclick={() => command('dialog', { dialog: 'find' })}>⌕ Find / Replace</button><button data-office-control="template-dialog" onclick={() => command('dialog', { dialog: 'templates' })}>New from Template</button><small>Editing</small></div>
  {:else if row.tab === 'Insert'}
    <div class="office-ribbon-group"><button data-office-control="insert-text" onclick={() => command('object.insert', { type: 'text' })}>▤ Text Box</button><button data-office-control="insert-picture" onclick={() => command('dialog', { dialog: 'image' })}>▧ Pictures</button><small>Text & Images</small></div>
    <div class="office-ribbon-group">{#each ['rectangle', 'ellipse', 'line'] as shape}<button data-office-control={`insert:${shape}`} onclick={() => command('object.insert', { type: 'shape', shape })}>{shape === 'rectangle' ? '▭' : shape === 'ellipse' ? '◯' : '╱'} {shape}</button>{/each}<small>Shapes</small></div>
  {:else if row.tab === 'Design'}
