    <div class="office-ribbon-group"><label>Background <input data-office-control="background" type="color" value={slide.background} onchange={event => command('background', { color: event.currentTarget.value })}/></label><button data-office-control="background-all" onclick={() => command('background', { color: slide.background, all: true })}>Apply to All</button><small>Customize</small></div>
  {:else if row.tab === 'Transitions'}
