    <div class="office-ribbon-group"><button data-office-control="view-normal" class:chosen={row.view.mode === 'normal'} onclick={() => command('view', { mode: 'normal' })}>Normal</button><button data-office-control="view-sorter" class:chosen={row.view.mode === 'sorter'} onclick={() => command('view', { mode: 'sorter' })}>Slide Sorter</button><small>Presentation Views</small></div><div class="office-ribbon-group"><label><input data-office-control="grid" type="checkbox" checked={row.view.grid} onchange={event => command('view', { grid: event.currentTarget.checked })}/>Gridlines</label><label>Zoom <input data-office-control="zoom" type="range" min="0.25" max="2" step="0.05" value={row.view.zoom} oninput={event => command('view', { zoom: Number(event.currentTarget.value) })}/></label><small>Show & Zoom</small></div><div class="office-ribbon-group"><label>Presentation title <input data-office-control="document-title" value={row.document.title} maxlength="128" onchange={event => command('title', { title: event.currentTarget.value })}/></label><small>Document</small></div>
  {:else if row.tab === 'ShapeFormat' || row.tab === 'PictureFormat'}
    <div class="office-ribbon-group"><button data-office-control="context-format" onclick={() => command('dialog', { dialog: 'format' })}>Format Object…</button><button data-office-control="context-duplicate" onclick={() => command('object.duplicate')}>Duplicate</button><button data-office-control="context-delete" onclick={() => command('object.delete')}>Delete</button><small>{row.tab === 'ShapeFormat' ? 'Shape' : 'Picture'}</small></div>
    {#if row.tab === 'ShapeFormat' && first}<div class="office-ribbon-group"><label>Shape Fill<input data-office-control="context-fill" type="color" value={first.fill} onchange={event => command('object.style', { fill: event.currentTarget.value })}/></label><select data-office-control="context-shape" aria-label="Change shape" value={first.shape} onchange={event => command('object.style', { shape: event.currentTarget.value })}>{#each ['rectangle', 'ellipse', 'line'] as shape}<option value={shape}>{shape}</option>{/each}</select><small>Shape Styles</small></div>{/if}
    <div class="office-ribbon-group">{#each ['front', 'back', 'forward', 'backward'] as direction}<button data-office-control={`context-arrange:${direction}`} onclick={() => command('object.arrange', { direction })}>{direction}</button>{/each}<small>Arrange</small></div>
    {#if first}<div class="office-ribbon-group">{#each ['width', 'height'] as field}<label>{field}<input data-office-control={`context-size:${field}`} type="number" min="1" max={field === 'width' ? row.document.width : row.document.height} value={first[field]} onchange={event => command('object.resize', { objectId: first.id, width: first.width, height: first.height, [field]: Number(event.currentTarget.value) })}/></label>{/each}<small>Size · Slide Coordinates</small></div>{/if}
  {/if}
  </div>
  {#if cap.golden}<p class="ppt-disclosure">{cap.disclosure}</p>{/if}
  <div class="office-workspace ppt-workspace" inert={!available || !active}>
    <aside class="ppt-slide-list" aria-label="Slides">{#each row.document.slides as item, index (item.id)}<div class="ppt-slide-row" class:chosen={item.id === slide.id} ondragover={event => event.preventDefault()} ondrop={event => reorderDrop(event, index)} role="group" aria-label={`Slide ${index + 1}`}><span>{index + 1}</span><button draggable="true" ondragstart={event => event.dataTransfer?.setData('application/x-jesteros-powerpoint-slide', item.id)} data-office-control={`slide:${item.id}`} aria-label={`Select slide ${index + 1}: ${item.objects.find(object => object.type === 'text')?.text ?? 'Blank'}`} aria-pressed={item.id === slide.id} onclick={() => command('slide.select', { slideId: item.id })}>{@render thumbnail(item)}</button></div>{/each}<button data-office-control="slide-list-insert" onclick={() => command('slide.insert', { layout: 'blank' })}>+ New Slide</button></aside>
    <main class="ppt-editor-area">
    {#if row.view.mode === 'sorter'}<div class="ppt-sorter" aria-label="Slide sorter">{#each row.document.slides as item, index (item.id)}<div ondragover={event => event.preventDefault()} ondrop={event => reorderDrop(event, index)} role="group" aria-label={`Slide ${index + 1}`}><button draggable="true" ondragstart={event => event.dataTransfer?.setData('application/x-jesteros-powerpoint-slide', item.id)} data-office-control={`sorter:${item.id}`} class:chosen={item.id === slide.id} onclick={() => command('slide.select', { slideId: item.id })}>{@render thumbnail(item)}</button><span>{index + 1}</span></div>{/each}</div>
    {:else}<div class="ppt-stage-scroll"><div class="ppt-stage-holder" style={`width:${row.view.zoom * 100}%`}><div bind:this={stage} class="ppt-stage" class:grid={row.view.grid} style={`aspect-ratio:${row.document.width}/${row.document.height};background-color:${slide.background}`} role="group" aria-label={`Editable slide ${row.document.slides.indexOf(slide) + 1}`} data-office-control="slide-canvas" tabindex="0" onclick={event => { if (event.target === stage) command('object.select', { objectIds: [] }); }}>{@render slideContents(slide, true)}</div></div></div>{/if}
    <footer class="ppt-slide-tools"><button data-office-control="slide-up" disabled={row.document.slides.indexOf(slide) === 0} onclick={() => command('slide.reorder', { slideId: slide.id, index: row.document.slides.indexOf(slide) - 1 })}>Move Slide Earlier</button><button data-office-control="slide-down" disabled={row.document.slides.indexOf(slide) === row.document.slides.length - 1} onclick={() => command('slide.reorder', { slideId: slide.id, index: row.document.slides.indexOf(slide) + 1 })}>Move Slide Later</button><button data-office-control="slide-delete" disabled={row.document.slides.length === 1} onclick={() => command('slide.delete', { slideId: slide.id })}>Delete Slide</button></footer>
    </main>
  </div>
  <footer class="office-statusbar ppt-status"><span role="status">{documentFonts.error || message || row.status || `Slide ${row.document.slides.indexOf(slide) + 1} of ${row.document.slides.length} · ${selected.length} selected · ${cap.version}`}</span><button data-office-control="status-show" onclick={() => command('presentation.start', { from: 'current' })}>▻ Slide Show</button><output>{Math.round(row.view.zoom * 100)}%</output></footer>
  </div>
  {#if row.dialog}
  <div class="ppt-dialog-backdrop"><section class="office-dialog ppt-dialog" role="dialog" aria-modal="true" aria-label={row.dialog}><header><strong>{row.dialog === 'image' ? 'Insert Picture' : row.dialog === 'format' ? 'Format Object' : row.dialog === 'find' ? 'Find and Replace' : row.dialog === 'templates' ? 'New Presentation' : row.dialog === 'close' ? 'Save your changes?' : row.dialog === 'save-as' ? 'Save As' : 'Microsoft PowerPoint'}</strong><button data-office-control="dialog-close" aria-label="Close dialog" onclick={() => command('dialog', { dialog: null })}>×</button></header>
  {#if row.dialog === 'templates'}<div class="office-templates ppt-templates">{#each Object.entries(POWERPOINT_TEMPLATES) as [template, label]}<button data-office-control={`template:${template}`} onclick={() => command('window.new', { template })}><b>▣</b>{label}</button>{/each}</div><p>Templates open as new editable presentations; your current document is preserved.</p>
  {:else if row.dialog === 'image'}<form onsubmit={insertImage}><button type="button" data-office-control="image-from-files" onclick={() => command('image.open')}>Choose from Files…</button><label>Or choose PNG / JPEG bytes <input data-office-control="image-file" type="file" accept="image/png,image/jpeg" onchange={readImage}/></label><label>Or paste genuine image dataURL <textarea data-office-control="image-data" rows="4" bind:value={imageData} maxlength="786432"></textarea></label><label>Media type<select data-office-control="image-mime" bind:value={imageMime}><option value="image/png">PNG</option><option value="image/jpeg">JPEG</option></select></label><p>Embedded local image bytes only. Remote URLs and placeholders are rejected.</p><button data-office-control="image-insert" disabled={!imageData}>Insert</button></form>
  {:else if row.dialog === 'format'}
    {#if first}<p>{selected.length} selected · {first.type}</p><fieldset><legend>Position and Size · slide coordinates</legend>{#each ['x', 'y', 'width', 'height'] as field}<label>{field}<input data-office-control={`geometry:${field}`} type="number" step="1" min={field === 'width' || field === 'height' ? 1 : 0} max={field === 'x' || field === 'width' ? row.document.width : row.document.height} value={first[field]} onchange={event => command('object.resize', { objectId: first.id, width: first.width, height: first.height, [field]: Number(event.currentTarget.value) })}/></label>{/each}</fieldset>
    {#if first.type !== 'image'}<label>Text<textarea data-office-control="format-text" value={first.text} maxlength="32768" rows="3" onchange={event => command('object.text', { objectId: first.id, text: event.currentTarget.value })}></textarea></label><label>Text Color<input data-office-control="format-color" type="color" value={first.color} onchange={event => command('object.style', { color: event.currentTarget.value })}/></label><label>Font Size<input data-office-control="format-font-size" type="number" min="6" max="200" value={first.fontSize} onchange={event => command('object.style', { fontSize: Number(event.currentTarget.value) })}/></label><label><input data-office-control="format-bold" type="checkbox" checked={first.bold} onchange={event => command('object.style', { bold: event.currentTarget.checked })}/>Bold</label>{/if}
    {#if first.type === 'shape'}<label>Fill<input data-office-control="shape-fill" type="color" value={first.fill} onchange={event => command('object.style', { fill: event.currentTarget.value })}/></label><label>Shape<select data-office-control="shape-kind" value={first.shape} onchange={event => command('object.style', { shape: event.currentTarget.value })}>{#each ['rectangle', 'ellipse', 'line'] as kind}<option value={kind}>{kind}</option>{/each}</select></label>{/if}
    <fieldset><legend>Arrange</legend>{#each ['front', 'back', 'forward', 'backward'] as direction}<button data-office-control={`arrange:${direction}`} onclick={() => command('object.arrange', { direction })}>{direction}</button>{/each}</fieldset><fieldset><legend>Align to Slide</legend>{#each ['left', 'center', 'right', 'top', 'middle', 'bottom'] as align}<button data-office-control={`align:${align}`} onclick={() => command('object.align', { align })}>{align}</button>{/each}</fieldset><button data-office-control="duplicate-selection" onclick={() => command('object.duplicate')}>Duplicate Selection</button>{:else}<p>Select an object on a slide to format it.</p>{/if}
  {:else if row.dialog === 'find'}<form onsubmit={event => { event.preventDefault(); if (findText) command('find', { text: findText }); }}><label>Find<input data-office-control="find-text" maxlength="256" bind:value={findText}/></label><label>Replace with<input data-office-control="replacement" maxlength="1024" bind:value={replacement}/></label><button data-office-control="find-next" disabled={!findText}>Find Next</button><button type="button" data-office-control="replace-all" disabled={!findText} onclick={() => command('replace', { find: findText, replacement })}>Replace All</button></form>
  {:else if row.dialog === 'save-as' || row.dialog === 'save'}<form onsubmit={event => { event.preventDefault(); command(row.dialog === 'save-as' ? 'saveAs' : 'save', filename ? { name: filename.endsWith('.pptx') ? filename : `${filename}.pptx` } : {}); }}><label>File name<input data-office-control="save-name" maxlength="120" bind:value={filename} placeholder={`${row.document.title}.pptx`}/></label><button data-office-control="save-confirm">Save PPTX</button></form>
  {:else if row.dialog === 'close'}<p>Save changes to “{row.document.title}” before closing?</p><button data-office-control="close-save" onclick={async () => { const result = await command('save'); if (current() && result?.status === 'applied') command('window.close'); }}>Save and Close</button><button data-office-control="close-discard" onclick={() => command('window.close', { discard: true })}>Discard and Close</button><button data-office-control="close-cancel" onclick={() => command('dialog', { dialog: null })}>Cancel</button>
  {:else if row.dialog === 'open'}<button data-office-control="open-choose" onclick={() => command('open')}>Choose a PPTX File…</button>
  {:else if row.dialog === 'export'}<button data-office-control="export-pdf" onclick={() => command('export', { format: 'pdf' })}>Export genuine PDF…</button>
  {:else}<p><strong>{cap.version}</strong></p><p>Installed font families are the original shared Font Book/Font Library sources, not proprietary Apple or Microsoft fonts. Enablement and source changes update this mounted document. Unavailable authored family names remain literal and use a safe browser rendering fallback; existing export font-embedding scopes are unchanged.</p><p>{cap.disclosure}</p><p>Edit text directly in selected objects. Drag the dotted grip to move; drag the lower-right handle to resize. Shift-click selects multiple objects. Arrow keys move selected objects; Shift-arrow moves by ten slide units. Slide thumbnails can be dragged to reorder.</p><p>PPTX import preserves the supported neutral slide subset. Unsupported charts, notes, mixed text runs and advanced animation features are rejected rather than silently flattened.</p><p>Presentation controls operate the current actual slide. Timed shows require authored scene-time advancement, not a host-clock timer.</p><button data-office-control="help-inspect" onclick={() => command('review.summary')}>Inspect Presentation</button>{/if}
  </section></div>
  {/if}
  {#if row.presentation.active && presented}
  <section class="ppt-presentation" role="region" aria-label="Slide Show" tabindex="0" data-office-control="presentation" style={`--ppt-ratio:${row.document.width / row.document.height}`}><div class="ppt-presentation-stage" style={`aspect-ratio:${row.document.width}/${row.document.height};background:${presented.background};opacity:${presented.transition === 'fade' ? progress : 1};transform:${presented.transition === 'push' ? `translateX(${(1 - progress) * 100}%)` : 'none'};clip-path:${presented.transition === 'wipe' ? `inset(0 0 0 ${(1 - progress) * 100}%)` : 'none'}`}>{@render slideContents(presented, false)}</div><nav class="ppt-presentation-controls" aria-label="Slide Show controls"><button data-office-control="show-prev" onclick={() => command('presentation.navigate', { delta: -1 })}>← Previous</button><output>Slide {row.document.slides.indexOf(presented) + 1} of {row.document.slides.length}</output><button data-office-control="show-next" onclick={() => command('presentation.navigate', { delta: 1 })}>Next →</button><button data-office-control="show-play" onclick={() => command('presentation.play', { playing: !row.presentation.playing })}>{row.presentation.playing ? 'Pause' : 'Play'}</button><label>Seconds per slide<input data-office-control="show-interval" type="number" min="0.25" max="600" step="0.25" value={row.presentation.intervalMs / 1000} onchange={event => command('presentation.play', { playing: row.presentation.playing, intervalMs: Math.round(Number(event.currentTarget.value) * 1000) })}/></label><label><input data-office-control="show-loop" type="checkbox" checked={row.presentation.loop} onchange={event => command('presentation.play', { playing: row.presentation.playing, loop: event.currentTarget.checked })}/>Loop</label><button data-office-control="show-end" onclick={() => command('presentation.stop')}>End Show (Esc)</button></nav><p class="ppt-presentation-clock">Authored scene time · no host-clock autoplay</p></section>
  {/if}
{:else}<p role="alert">The original PowerPoint document window is unavailable.</p>{/if}
</section>
